    private void btnAyudaCantidadConfirmadaActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_btnAyudaCantidadConfirmadaActionPerformed
        mostrarModalAyuda("En este campo puede escribir la cantidad que se ha contado en su inventario manual, para actualizarla al stock real en dado caso que no concuerden.");
    }//GEN-LAST:event_btnAyudaCantidadConfirmadaActionPerformed

    private void btnAyudaConfirmarActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_btnAyudaConfirmarActionPerformed
        mostrarModalAyuda("Este campo le permite separar visualmente cuales productos ya ha verificado en su inventario manual, ademas es el punto principal para aquellos en donde se "
                + "desea actualizar algun cambio de valor se pueda almacenar correctamente en la base de datos.");
    }//GEN-LAST:event_btnAyudaConfirmarActionPerformed

    

