    public void configurarModoVerificacion( boolean modoVerificar){
        contenedorTituloCantidadConfirmada.setVisible(modoVerificar);
        contenedorTituloConfirmar.setVisible(modoVerificar);
        contenedorTitulosTabla.revalidate(); // Re calcula el diseño GridBagLayout
        contenedorTitulosTabla.repaint();    // Redibuja el panel en pantalla
    }
    
    public PanelBusquedaYAccionLibre getPanelBusquedaYAccionLibre(){
        return panelBusquedaYAccionLibre;
    }
    
    /*
    Metodo para poder agregar toda la lista de productos recibida, por medio de
    LinkedHashMap mantenemos el orden en el cual ha sido enviada.
    */
    public void inyectarFilas( LinkedHashMap<Integer, FilaTablaInventario> filasTablaInventario ){
        contenedorContenidoTabla.removeAll();
        
        filasTablaInventario.values().forEach(fila -> {
            contenedorContenidoTabla.add(fila);
        });
        
        redibujarPanel();
    }
    
    
    private void redibujarPanel(){
        // Avisar a Swing que recalcule los tamaños y redibuje el panel
        contenedorContenidoTabla.revalidate();
        contenedorContenidoTabla.repaint();
    }
  
    
    
    /* 
        Metodos para dialogos de mensajes de Alertas
    */
     
    // Metodo para optener cual es el frame padre de la vista JPanel modulo de ventas
    public java.awt.Window getVentanaPadre(){
        return javax.swing.SwingUtilities.getWindowAncestor( this );
    }
    
    public void mostrarModalError (String mensaje){
        DialogoAlerta.mostrarError( getVentanaPadre(), "Error", mensaje);
    } 
    
    public void mostrarModalExito (String mensaje){
        DialogoAlerta.mostrarExito(getVentanaPadre(), "Exito", mensaje);
    } 
    
    public boolean mostrarModalAdvertenciaConRespuesta (String mensaje){
        return DialogoAlerta.mostrarAdvertenciaConRespuesta(getVentanaPadre(), "Advertencia", mensaje);
    } 
    
    public void mostrarModalAyuda (String mensaje){
        DialogoAlerta.mostrarInformacion(getVentanaPadre(), "Ayuda", mensaje);
    } 

    
